                            if test_in[nr][nc] == test_in[cr][cc] and (nr,nc) not in visited:
                                queue.append((nr,nc))

            if len(comp) == 1:
                r0, c0 = comp[0]
                neigh_4 = [test_in[r0+dr][c0+dc] for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)] 
                          if 0 <= r0+dr < H and 0 <= c0+dc < W]
                counts = Counter(neigh_4)
                max_count = max(counts.values())
                ties = sorted([v for v, cnt in counts.items() if cnt == max_count])
                new_val = min(ties)
                result[r0][c0] = new_val

# Submit on last line
print('Submit:', {"action": "submit", "grid": result})
